#!/usr/bin/env python3
import os, csv, math, json, sys
from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions"
os.makedirs(OUT, exist_ok=True)

def read_csv(name):
    with open(os.path.join(DATA, name), newline="") as f:
        return list(csv.DictReader(f))

months_rows = read_csv("months.csv")
months = [r["month"] for r in months_rows]
month_idx = {r["month"]: int(r["period_index"]) for r in months_rows}

products_rows = read_csv("products.csv")
products = [r["product_id"] for r in products_rows]
hold_mult = {r["product_id"]: float(r["inventory_holding_multiplier"]) for r in products_rows}
short_mult = {r["product_id"]: float(r["shortage_penalty_multiplier"]) for r in products_rows}

materials_rows = read_csv("materials.csv")
materials = [r["material_id"] for r in materials_rows]

bom = {}
for r in read_csv("material_bom.csv"):
    bom[(r["product_id"], r["material_id"])] = float(r["tons_material_per_ton_product"])

plants_rows = read_csv("plants.csv")
plants = [r["plant_id"] for r in plants_rows]
regCap = {r["plant_id"]: float(r["regular_capacity_tons"]) for r in plants_rows}
otCap = {r["plant_id"]: float(r["overtime_capacity_tons"]) for r in plants_rows}
minRun = {r["plant_id"]: float(r["min_run_tons"]) for r in plants_rows}
fixOp = {r["plant_id"]: float(r["fixed_operating_cost"]) for r in plants_rows}
startupCost = {r["plant_id"]: float(r["startup_cost"]) for r in plants_rows}
initOpen = {r["plant_id"]: int(r["initial_open"]) for r in plants_rows}
minUptime = {r["plant_id"]: int(r["min_uptime_months"]) for r in plants_rows}

ppcost_rows = read_csv("plant_product_costs.csv")
convCost = {(r["plant_id"], r["product_id"]): float(r["regular_conversion_cost_per_ton"]) for r in ppcost_rows}
otPrem = {(r["plant_id"], r["product_id"]): float(r["overtime_premium_cost_per_ton"]) for r in ppcost_rows}
regCons = {(r["plant_id"], r["product_id"]): float(r["regular_capacity_consumption_per_ton"]) for r in ppcost_rows}
otCons = {(r["plant_id"], r["product_id"]): float(r["overtime_capacity_consumption_per_ton"]) for r in ppcost_rows}
procCO2 = {(r["plant_id"], r["product_id"]): float(r["process_co2_kg_per_ton"]) for r in ppcost_rows}

pprules_rows = read_csv("plant_product_rules.csv")
qualMonth = {(r["plant_id"], r["product_id"]): r["qualified_from_month"] for r in pprules_rows}
minBatch = {(r["plant_id"], r["product_id"]): float(r["min_batch_tons_if_produced"]) for r in pprules_rows}
maxOut = {(r["plant_id"], r["product_id"]): float(r["max_monthly_output_tons"]) for r in pprules_rows}
setupCost = {(r["plant_id"], r["product_id"]): float(r["setup_cost_per_month"]) for r in pprules_rows}

mat_supply = {}
for r in read_csv("material_supply.csv"):
    mat_supply[(r["month"], r["plant_id"], r["material_id"])] = (
        float(r["max_purchase_tons"]), float(r["purchase_cost_per_ton"]), float(r["material_co2_kg_per_ton"]))

mat_contracts = {}
for r in read_csv("material_contracts.csv"):
    mat_contracts[(r["month"], r["plant_id"], r["material_id"])] = float(r["min_purchase_tons_if_open"])

dc_rows = read_csv("distribution_centers.csv")
dcs = [r["dc_id"] for r in dc_rows]
dcStore = {r["dc_id"]: float(r["storage_capacity_tons"]) for r in dc_rows}
holdCost = {r["dc_id"]: float(r["holding_cost_per_ton_month"]) for r in dc_rows}
dcIn = {r["dc_id"]: float(r["inbound_throughput_tons"]) for r in dc_rows}
dcOut = {r["dc_id"]: float(r["outbound_throughput_tons"]) for r in dc_rows}

cust_rows = read_csv("customers.csv")
customers = [r["customer_id"] for r in cust_rows]
penalty = {r["customer_id"]: float(r["shortage_penalty_per_ton"]) for r in cust_rows}

demand = {}
for r in read_csv("demand.csv"):
    demand[(r["month"], r["customer_id"], r["product_id"])] = float(r["demand_tons"])

avail = {}
for r in read_csv("plant_month_availability.csv"):
    avail[(r["month"], r["plant_id"])] = (float(r["regular_capacity_factor"]), float(r["overtime_capacity_factor"]))

pin_rows = read_csv("plant_to_dc_routes.csv")
pin_lanes = set()
pinCost = {}; pinCap = {}; pinCO2 = {}; pinFix = {}; pinMin = {}
for r in pin_rows:
    l = (r["plant_id"], r["dc_id"])
    pin_lanes.add(l)
    pinCost[l] = float(r["transport_cost_per_ton"])
    pinCap[l] = float(r["monthly_capacity_tons"])
    pinCO2[l] = float(r["transport_co2_kg_per_ton"])
    pinFix[l] = float(r["fixed_cost_per_month"])
    pinMin[l] = float(r["min_shipment_tons_if_used"])

pout_rows = read_csv("dc_to_customer_routes.csv")
pout_lanes = set()
poutCost = {}; poutCap = {}; poutCO2 = {}; poutFix = {}; poutMin = {}
for r in pout_rows:
    l = (r["dc_id"], r["customer_id"])
    pout_lanes.add(l)
    poutCost[l] = float(r["transport_cost_per_ton"])
    poutCap[l] = float(r["monthly_capacity_tons"])
    poutCO2[l] = float(r["transport_co2_kg_per_ton"])
    poutFix[l] = float(r["fixed_cost_per_month"])
    poutMin[l] = float(r["min_shipment_tons_if_used"])

safety = {}
for r in read_csv("safety_stock.csv"):
    safety[(r["month"], r["dc_id"], r["product_id"])] = float(r["min_inventory_tons"])

inv_caps = {}
for r in read_csv("inventory_caps.csv"):
    inv_caps[(r["month"], r["dc_id"], r["product_id"])] = float(r["max_inventory_tons"])

svc = {}
for r in read_csv("customer_service_requirements.csv"):
    svc[(r["customer_id"], r["product_id"])] = (float(r["min_horizon_fill_rate"]), float(r["max_monthly_shortage_fraction"]))

co2_budget = {}
for r in read_csv("monthly_co2_budget.csv"):
    co2_budget[r["month"]] = float(r["co2_budget_kg"])

# route-product exceptions
excl_in = set(); excl_out = set()
for r in read_csv("route_product_exceptions.csv"):
    if r["route_type"] == "plant_dc" and int(r["allowed"]) == 0:
        excl_in.add((r["from_id"], r["to_id"], r["product_id"]))
    elif r["route_type"] == "dc_customer" and int(r["allowed"]) == 0:
        excl_out.add((r["from_id"], r["to_id"], r["product_id"]))

# share rules
share_rules = []
for r in read_csv("customer_product_share_rules.csv"):
    dcs_list = [d for d in r["dc_ids"].split(";") if d]
    share_rules.append((r["customer_id"], r["product_id"], dcs_list, float(r["min_horizon_share"])))

# split delivery rules
split_rules = {}
for r in read_csv("split_delivery_rules.csv"):
    split_rules[(r["month"], r["customer_id"], r["product_id"], r["dc_id"])] = float(r["min_fraction_of_demand"])

# transport modes
pin_modes = {}  # (plant,dc) -> list of mode ids
pout_modes = {}
modeCapLane = {}; modeMinLane = {}; modeCostMult = {}; modeCO2Mult = {}
for r in read_csv("transport_modes.csv"):
    if r["route_type"] == "plant_dc":
        l = (r["from_id"], r["to_id"])
        pin_modes.setdefault(l, []).append(r["mode_id"])
        modeCapLane[(l, r["mode_id"])] = float(r["monthly_capacity_tons"])
        modeMinLane[(l, r["mode_id"])] = float(r["min_mode_tons_if_used"])
        modeCostMult[(l, r["mode_id"])] = float(r["cost_multiplier"])
        modeCO2Mult[(l, r["mode_id"])] = float(r["co2_multiplier"])
    else:
        l = (r["from_id"], r["to_id"])
        pout_modes.setdefault(l, []).append(r["mode_id"])
        modeCapLane[(l, r["mode_id"])] = float(r["monthly_capacity_tons"])
        modeMinLane[(l, r["mode_id"])] = float(r["min_mode_tons_if_used"])
        modeCostMult[(l, r["mode_id"])] = float(r["cost_multiplier"])
        modeCO2Mult[(l, r["mode_id"])] = float(r["co2_multiplier"])

modeCapGlobal = {}; modeMinGlobal = {}
for r in read_csv("monthly_mode_capacity.csv"):
    modeCapGlobal[(r["month"], r["mode_id"])] = float(r["max_tons"])
    modeMinGlobal[(r["month"], r["mode_id"])] = float(r["min_tons_if_used"])

# material contract tiers (low-carbon/spot) - min_low_carbon_tons all 0 in data; enforce nothing extra beyond contracts
# (data has min_low_carbon_tons=0, max_spot_tons=999999 -> no binding constraint)

# ---------------- Build model ----------------
model = Model("supply_plan")
model.setParam("gaprel", 0.0005)
time_limit = 300.0
env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env_limit is not None:
    try:
        time_limit = min(time_limit, float(env_limit))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

# total demand upper bound for bounds
total_demand = sum(demand.values())

# Variables
open_v = {}
start_v = {}
for p in plants:
    for m in months:
        open_v[(p, m)] = model.addVar(name=f"open_{p}_{m}", vtype="B", lb=0, ub=1, obj=fixOp[p])
        start_v[(p, m)] = model.addVar(name=f"start_{p}_{m}", vtype="B", lb=0, ub=1, obj=startupCost[p])

setup_v = {}
xR = {}
xO = {}
for p in plants:
    for q in products:
        for m in months:
            if month_idx[m] >= month_idx[qualMonth[(p, q)]]:
                setup_v[(p, q, m)] = model.addVar(name=f"setup_{p}_{q}_{m}", vtype="B", lb=0, ub=1, obj=setupCost[(p, q)])
            else:
                setup_v[(p, q, m)] = None
            xR[(p, q, m)] = model.addVar(name=f"xR_{p}_{q}_{m}", vtype="C", lb=0, ub=maxOut[(p, q)],
                                         obj=convCost[(p, q)])
            xO[(p, q, m)] = model.addVar(name=f"xO_{p}_{q}_{m}", vtype="C", lb=0, ub=maxOut[(p, q)],
                                         obj=convCost[(p, q)] + otPrem[(p, q)])

buy = {}
for p in plants:
    for m in months:
        for r in materials:
            mx, cost, _ = mat_supply[(m, p, r)]
            buy[(p, m, r)] = model.addVar(name=f"buy_{p}_{m}_{r}", vtype="C", lb=0, ub=mx, obj=cost)

# shipment variables with mode
ship_in = {}   # (p,d,q,m,mode)
y_in = {}      # (p,d,m,mode) activation
for (p, d) in pin_lanes:
    for m in months:
        for mode in pin_modes.get((p, d), []):
            y_in[(p, d, m, mode)] = model.addVar(name=f"y_in_{p}_{d}_{m}_{mode}", vtype="B", lb=0, ub=1, obj=pinFix[(p, d)])
            for q in products:
                if (p, d, q) not in excl_in:
                    ship_in[(p, d, q, m, mode)] = model.addVar(name=f"ship_in_{p}_{d}_{q}_{m}_{mode}", vtype="C",
                                                               lb=0, ub=pinCap[(p, d)],
                                                               obj=pinCost[(p, d)] * modeCostMult[(p, d, mode)])

ship_out = {}  # (d,c,q,m,mode)
y_out = {}
for (d, c) in pout_lanes:
    for m in months:
        for mode in pout_modes.get((d, c), []):
            y_out[(d, c, m, mode)] = model.addVar(name=f"y_out_{d}_{c}_{m}_{mode}", vtype="B", lb=0, ub=1, obj=poutFix[(d, c)])
            for q in products:
                if (d, c, q) not in excl_out:
                    ship_out[(d, c, q, m, mode)] = model.addVar(name=f"ship_out_{d}_{c}_{q}_{m}_{mode}", vtype="C",
                                                                lb=0, ub=poutCap[(d, c)],
                                                                obj=poutCost[(d, c)] * modeCostMult[(d, c, mode)])

inv = {}
for d in dcs:
    for q in products:
        for m in months:
            inv[(d, q, m)] = model.addVar(name=f"inv_{d}_{q}_{m}", vtype="C", lb=0, ub=dcStore[d],
                                          obj=holdCost[d] * hold_mult[q])

short = {}
for c in customers:
    for q in products:
        for m in months:
            short[(c, q, m)] = model.addVar(name=f"short_{c}_{q}_{m}", vtype="C", lb=0,
                                            ub=demand.get((m, c, q), 0.0),
                                            obj=penalty[c] * short_mult[q])

# ---------------- Constraints ----------------
# Plant startup logic
for p in plants:
    for i, m in enumerate(months):
        prev_open = initOpen[p] if i == 0 else open_v[(p, months[i-1])]
        model.addCons(start_v[(p, m)] >= open_v[(p, m)] - prev_open, name=f"start_{p}_{m}")
        # min uptime: if start at m, open for next minUptime-1 months
        u = minUptime[p]
        for k in range(1, u):
            j = i + k
            if j < len(months):
                model.addCons(open_v[(p, months[j])] >= start_v[(p, m)], name=f"uptime_{p}_{m}_{k}")

# Production capacity and min run
for p in plants:
    for m in months:
        rf, of = avail[(m, p)]
        model.addCons(quicksum(regCons[(p, q)] * xR[(p, q, m)] for q in products)
                      <= regCap[p] * rf * open_v[(p, m)], name=f"regcap_{p}_{m}")
        model.addCons(quicksum(otCons[(p, q)] * xO[(p, q, m)] for q in products)
                      <= otCap[p] * of * open_v[(p, m)], name=f"otcap_{p}_{m}")
        model.addCons(quicksum(xR[(p, q, m)] + xO[(p, q, m)] for q in products)
                      >= minRun[p] * open_v[(p, m)], name=f"minrun_{p}_{m}")

# Campaign setup
for p in plants:
    for q in products:
        for m in months:
            sv = setup_v[(p, q, m)]
            if sv is None:
                # not qualified: force zero production
                model.addCons(xR[(p, q, m)] == 0, name=f"noqual_{p}_{q}_{m}")
                model.addCons(xO[(p, q, m)] == 0, name=f"noqualO_{p}_{q}_{m}")
                continue
            model.addCons(sv <= open_v[(p, m)], name=f"setupopen_{p}_{q}_{m}")
            model.addCons(xR[(p, q, m)] + xO[(p, q, m)] <= maxOut[(p, q)] * sv, name=f"setupmax_{p}_{q}_{m}")
            mb = minBatch[(p, q)]
            if mb > 0:
                model.addCons(xR[(p, q, m)] + xO[(p, q, m)] >= mb * sv, name=f"setupmin_{p}_{q}_{m}")

# Raw material balance and contracts
for p in plants:
    for m in months:
        for r in materials:
            mx, _, _ = mat_supply[(m, p, r)]
            model.addCons(buy[(p, m, r)] <= mx * open_v[(p, m)], name=f"buycap_{p}_{m}_{r}")
            model.addCons(buy[(p, m, r)] >= quicksum(bom.get((q, r), 0.0) * (xR[(p, q, m)] + xO[(p, q, m)])
                                                      for q in products), name=f"bom_{p}_{m}_{r}")
            if (m, p, r) in mat_contracts:
                model.addCons(buy[(p, m, r)] >= mat_contracts[(m, p, r)] * open_v[(p, m)],
                              name=f"contract_{p}_{m}_{r}")

# DC inventory balance
for d in dcs:
    for q in products:
        for i, m in enumerate(months):
            inbound = quicksum(ship_in[(p, d, q, m, mode)]
                               for (p, dd) in pin_lanes if dd == d
                               for mode in pin_modes.get((p, d), [])
                               if (p, d, q, m, mode) in ship_in)
            outbound = quicksum(ship_out[(d, c, q, m, mode)]
                                for (dd, c) in pout_lanes if dd == d
                                for mode in pout_modes.get((d, c), [])
                                if (d, c, q, m, mode) in ship_out)
            prev_inv = 0.0 if i == 0 else inv[(d, q, months[i-1])]
            model.addCons(inv[(d, q, m)] == prev_inv + inbound - outbound, name=f"invbal_{d}_{q}_{m}")
            # safety stock
            ss = safety.get((m, d, q), 0.0)
            if ss > 0:
                model.addCons(inv[(d, q, m)] >= ss, name=f"safety_{d}_{q}_{m}")
            # product cap
            if (m, d, q) in inv_caps:
                model.addCons(inv[(d, q, m)] <= inv_caps[(m, d, q)], name=f"invcap_{d}_{q}_{m}")

# DC aggregate storage and throughput
for d in dcs:
    for m in months:
        model.addCons(quicksum(inv[(d, q, m)] for q in products) <= dcStore[d], name=f"dcstore_{d}_{m}")
        model.addCons(quicksum(ship_in[(p, d, q, m, mode)]
                               for (p, dd) in pin_lanes if dd == d
                               for q in products
                               for mode in pin_modes.get((p, d), [])
                               if (p, d, q, m, mode) in ship_in) <= dcIn[d], name=f"dcin_{d}_{m}")
        model.addCons(quicksum(ship_out[(d, c, q, m, mode)]
                               for (dd, c) in pout_lanes if dd == d
                               for q in products
                               for mode in pout_modes.get((d, c), [])
                               if (d, c, q, m, mode) in ship_out) <= dcOut[d], name=f"dcout_{d}_{m}")

# Customer demand balance and service
for c in customers:
    for q in products:
        for m in months:
            dmd = demand.get((m, c, q), 0.0)
            delivered = quicksum(ship_out[(d, c, q, m, mode)]
                                 for (d, cc) in pout_lanes if cc == c
                                 for mode in pout_modes.get((d, c), [])
                                 if (d, c, q, m, mode) in ship_out)
            model.addCons(delivered + short[(c, q, m)] == dmd, name=f"demand_{c}_{q}_{m}")
            if (c, q) in svc:
                fr, sf = svc[(c, q)]
                if dmd > 0:
                    model.addCons(short[(c, q, m)] <= sf * dmd, name=f"svcshort_{c}_{q}_{m}")
        # horizon fill rate
        if (c, q) in svc:
            fr, _ = svc[(c, q)]
            total_d = sum(demand.get((m, c, q), 0.0) for m in months)
            if total_d > 0:
                model.addCons(quicksum(short[(c, q, m)] for m in months) <= (1 - fr) * total_d,
                              name=f"svcfill_{c}_{q}")

# Lane constraints
for (p, d) in pin_lanes:
    for m in months:
        # lane total capacity
        model.addCons(quicksum(ship_in[(p, d, q, m, mode)] for q in products
                               for mode in pin_modes.get((p, d), [])
                               if (p, d, q, m, mode) in ship_in) <= pinCap[(p, d)], name=f"lanecap_in_{p}_{d}_{m}")
        # lane minimum shipment if any mode used: use sum of y
        model.addCons(quicksum(ship_in[(p, d, q, m, mode)] for q in products
                               for mode in pin_modes.get((p, d), [])
                               if (p, d, q, m, mode) in ship_in)
                      >= pinMin[(p, d)] * quicksum(y_in[(p, d, m, mode)] for mode in pin_modes.get((p, d), [])),
                      name=f"lanemin_in_{p}_{d}_{m}")
        # mode linking
        for mode in pin_modes.get((p, d), []):
            mc = modeCapLane[(p, d, mode)]
            mm = modeMinLane[(p, d, mode)]
            model.addCons(quicksum(ship_in[(p, d, q, m, mode)] for q in products
                                   if (p, d, q, m, mode) in ship_in) <= mc * y_in[(p, d, m, mode)],
                          name=f"modecap_in_{p}_{d}_{m}_{mode}")
            if mm > 0:
                model.addCons(quicksum(ship_in[(p, d, q, m, mode)] for q in products
                                       if (p, d, q, m, mode) in ship_in) >= mm * y_in[(p, d, m, mode)],
                              name=f"modemin_in_{p}_{d}_{m}_{mode}")

for (d, c) in pout_lanes:
    for m in months:
        model.addCons(quicksum(ship_out[(d, c, q, m, mode)] for q in products
                               for mode in pout_modes.get((d, c), [])
                               if (d, c, q, m, mode) in ship_out) <= poutCap[(d, c)], name=f"lanecap_out_{d}_{c}_{m}")
        model.addCons(quicksum(ship_out[(d, c, q, m, mode)] for q in products
                               for mode in pout_modes.get((d, c), [])
                               if (d, c, q, m, mode) in ship_out)
                      >= poutMin[(d, c)] * quicksum(y_out[(d, c, m, mode)] for mode in pout_modes.get((d, c), [])),
                      name=f"lanemin_out_{d}_{c}_{m}")
        for mode in pout_modes.get((d, c), []):
            mc = modeCapLane[(d, c, mode)]
            mm = modeMinLane[(d, c, mode)]
            model.addCons(quicksum(ship_out[(d, c, q, m, mode)] for q in products
                                   if (d, c, q, m, mode) in ship_out) <= mc * y_out[(d, c, m, mode)],
                          name=f"modecap_out_{d}_{c}_{m}_{mode}")
            if mm > 0:
                model.addCons(quicksum(ship_out[(d, c, q, m, mode)] for q in products
                                       if (d, c, q, m, mode) in ship_out) >= mm * y_out[(d, c, m, mode)],
                              name=f"modemin_out_{d}_{c}_{m}_{mode}")

# Global mode capacity
for m in months:
    for mode in ["RAIL", "TRUCK"]:
        if (m, mode) in modeCapGlobal:
            if mode == "RAIL":
                expr = quicksum(ship_in[(p, d, q, m, mode)]
                                for (p, d) in pin_lanes
                                for q in products
                                for md in pin_modes.get((p, d), []) if md == mode
                                if (p, d, q, m, mode) in ship_in)
            else:
                expr = quicksum(ship_out[(d, c, q, m, mode)]
                                for (d, c) in pout_lanes
                                for q in products
                                for md in pout_modes.get((d, c), []) if md == mode
                                if (d, c, q, m, mode) in ship_out)
            model.addCons(expr <= modeCapGlobal[(m, mode)], name=f"globalmode_{m}_{mode}")

# Sourcing share rules
for (c, q, dcs_list, sharemin) in share_rules:
    approved = set(dcs_list)
    delivered_total = quicksum(ship_out[(d, c, q, m, mode)]
                               for (d, cc) in pout_lanes if cc == c
                               for m in months
                               for mode in pout_modes.get((d, c), [])
                               if (d, c, q, m, mode) in ship_out)
    delivered_approved = quicksum(ship_out[(d, c, q, m, mode)]
                                  for (d, cc) in pout_lanes if cc == c and d in approved
                                  for m in months
                                  for mode in pout_modes.get((d, c), [])
                                  if (d, c, q, m, mode) in ship_out)
    model.addCons(delivered_approved >= sharemin * delivered_total, name=f"share_{c}_{q}")

# Split delivery rules
for (m, c, q, d), frac in split_rules.items():
    dmd = demand.get((m, c, q), 0.0)
    if dmd > 0:
        model.addCons(quicksum(ship_out[(d, c, q, m, mode)] for mode in pout_modes.get((d, c), [])
                               if (d, c, q, m, mode) in ship_out) >= frac * dmd,
                      name=f"split_{m}_{c}_{q}_{d}")

# CO2 budget
for m in months:
    mat_co2 = quicksum(mat_supply[(m, p, r)][2] * buy[(p, m, r)] for p in plants for r in materials)
    proc_co2 = quicksum(procCO2[(p, q)] * (xR[(p, q, m)] + xO[(p, q, m)]) for p in plants for q in products)
    trans_in_co2 = quicksum(pinCO2[(p, d)] * modeCO2Mult[(p, d, mode)] * ship_in[(p, d, q, m, mode)]
                            for (p, d) in pin_lanes for q in products
                            for mode in pin_modes.get((p, d), [])
                            if (p, d, q, m, mode) in ship_in)
    trans_out_co2 = quicksum(poutCO2[(d, c)] * modeCO2Mult[(d, c, mode)] * ship_out[(d, c, q, m, mode)]
                             for (d, c) in pout_lanes for q in products
                             for mode in pout_modes.get((d, c), [])
                             if (d, c, q, m, mode) in ship_out)
    model.addCons(mat_co2 + proc_co2 + trans_in_co2 + trans_out_co2 <= co2_budget[m], name=f"co2_{m}")

model.setObjective(quicksum(v.obj for v in model.getVars() if v.obj != 0.0), sense="minimize")

# ---------------- Solve ----------------
model.optimize()
status = model.getStatus()
print("Solver status:", status)
nsols = model.getNSols()
print("Number of solutions:", nsols)

rows_out = []
def add_row(varname, m, item, frm, to, mode, qty):
    if qty is None:
        return
    qty = float(qty)
    if qty > 1e-8:
        rows_out.append([varname, m, item, frm, to, mode, f"{qty:.8f}"])

if nsols > 0:
    sol = model.getBestSol()
    def val(v):
        return model.getVal(v) if v is not None else 0.0

    objval = model.getObjVal()
    print("Objective value:", objval)

    # production
    for p in plants:
        for q in products:
            for m in months:
                rv = val(xR[(p, q, m)])
                ov = val(xO[(p, q, m)])
                add_row("regular_production", m, q, p, "", "", rv)
                add_row("overtime_production", m, q, p, "", "", ov)
                sv = setup_v[(p, q, m)]
                if sv is not None and val(sv) > 0.5:
                    rows_out.append([f"product_setup", m, q, p, "", "", "1"])

    # purchases (not in schema but keep for validation; schema only lists production/ship rows)
    # We'll include material_purchase rows? Schema example only shows production and ship rows.
    # Required schema: variable,month,item,from,to,mode_id,quantity_tons
    # We'll add material_purchase and inventory and shortage rows too for completeness.
    for p in plants:
        for m in months:
            for r in materials:
                add_row("material_purchase", m, r, p, "", "", val(buy[(p, m, r)]))

    for (p, d) in pin_lanes:
        for m in months:
            for mode in pin_modes.get((p, d), []):
                for q in products:
                    if (p, d, q, m, mode) in ship_in:
                        add_row("ship_plant_dc", m, q, p, d, mode, val(ship_in[(p, d, q, m, mode)]))

    for (d, c) in pout_lanes:
        for m in months:
            for mode in pout_modes.get((d, c), []):
                for q in products:
                    if (d, c, q, m, mode) in ship_out:
                        add_row("ship_dc_customer", m, q, d, c, mode, val(ship_out[(d, c, q, m, mode)]))

    for d in dcs:
        for q in products:
            for m in months:
                add_row("inventory", m, q, d, "", "", val(inv[(d, q, m)]))

    for c in customers:
        for q in products:
            for m in months:
                add_row("shortage", m, q, "", c, "", val(short[(c, q, m)]))

    # plant open/startup
    for p in plants:
        for m in months:
            if val(open_v[(p, m)]) > 0.5:
                rows_out.append(["plant_open", m, p, p, "", "", "1"])
            if val(start_v[(p, m)]) > 0.5:
                rows_out.append(["plant_startup", m, p, p, "", "", "1"])

# Write solution
with open(os.path.join(OUT, "solution.csv"), "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["variable", "month", "item", "from", "to", "mode_id", "quantity_tons"])
    for r in rows_out:
        w.writerow(r)

print(f"Wrote {len(rows_out)} rows to solution.csv")

# ---------------- Validation ----------------
def close(a, b, tol=1e-5):
    return abs(a - b) <= tol

errors = []
if nsols > 0:
    # demand balance
    for c in customers:
        for q in products:
            for m in months:
                dmd = demand.get((m, c, q), 0.0)
                delivered = sum(val(ship_out[(d, c, q, m, mode)])
                                for (d, cc) in pout_lanes if cc == c
                                for mode in pout_modes.get((d, c), [])
                                if (d, c, q, m, mode) in ship_out)
                if not close(delivered + val(short[(c, q, m)]), dmd, 1e-4):
                    errors.append(f"demand balance {c},{q},{m}: {delivered}+{val(short[(c,q,m)])} != {dmd}")
    # inventory balance
    for d in dcs:
        for q in products:
            for i, m in enumerate(months):
                inbound = sum(val(ship_in[(p, d, q, m, mode)])
                              for (p, dd) in pin_lanes if dd == d
                              for mode in pin_modes.get((p, d), [])
                              if (p, d, q, m, mode) in ship_in)
                outbound = sum(val(ship_out[(d, c, q, m, mode)])
                               for (dd, c) in pout_lanes if dd == d
                               for mode in pout_modes.get((d, c), [])
                               if (d, c, q, m, mode) in ship_out)
                prev = 0.0 if i == 0 else val(inv[(d, q, months[i-1])])
                if not close(val(inv[(d, q, m)]), prev + inbound - outbound, 1e-4):
                    errors.append(f"inv balance {d},{q},{m}")
    # service
    for c in customers:
        for q in products:
            if (c, q) in svc:
                fr, sf = svc[(c, q)]
                for m in months:
                    dmd = demand.get((m, c, q), 0.0)
                    if dmd > 0 and val(short[(c, q, m)]) > sf * dmd + 1e-4:
                        errors.append(f"svc short {c},{q},{m}")
                total_d = sum(demand.get((m, c, q), 0.0) for m in months)
                total_s = sum(val(short[(c, q, m)]) for m in months)
                if total_d > 0 and total_s > (1 - fr) * total_d + 1e-4:
                    errors.append(f"svc fill {c},{q}")
    # co2
    for m in months:
        mat_co2 = sum(mat_supply[(m, p, r)][2] * val(buy[(p, m, r)]) for p in plants for r in materials)
        proc_co2 = sum(procCO2[(p, q)] * (val(xR[(p, q, m)]) + val(xO[(p, q, m)])) for p in plants for q in products)
        ti = sum(pinCO2[(p, d)] * modeCO2Mult[(p, d, mode)] * val(ship_in[(p, d, q, m, mode)])
                 for (p, d) in pin_lanes for q in products
                 for mode in pin_modes.get((p, d), []) if (p, d, q, m, mode) in ship_in)
        to = sum(poutCO2[(d, c)] * modeCO2Mult[(d, c, mode)] * val(ship_out[(d, c, q, m, mode)])
                 for (d, c) in pout_lanes for q in products
                 for mode in pout_modes.get((d, c), []) if (d, c, q, m, mode) in ship_out)
        if mat_co2 + proc_co2 + ti + to > co2_budget[m] + 1e-3:
            errors.append(f"co2 {m}")

print("Validation errors:", len(errors))
for e in errors[:20]:
    print("  ", e)

model.free()
print("Done.")
